  list("Medium", "Volume indicators and market overview (volume_indicators.R, market_overview.R)",
       "On-Balance Volume and weighted OBV; price with volume and volume statistics.",
       "Require volume confirmation for breakout scenarios (OBV rising for a buy breakout). Note: Capital.com volume is tick volume, so use it as relative, not absolute.",
       "Filters out breakouts without participation, a common source of stop-outs."),
  list("Low", "Composite Analysis (composite_analysis.R)",
       "Comparative performance, correlation heatmap, risk-return scatter.",
       "Before opening a second position, show its correlation with the open ones (e.g. Brent and WTI, or GBP pairs) and count correlated risk together against your cap.",
       "Prevents doubling the same bet without noticing."),
  list("Low", "Psychology: Ten Steps (ten_steps.R) and the guided workbench (unit3_workbench_guides.R)",
       "The course's ten steps (hard work, confidence, education, mentor, discipline...) and guided explanations.",
       "A short pre-trade checklist in the ticket (plan followed, reason written, mood) that must be ticked; the C analysis already notes when the reasoning boxes were empty.",
       "On 5 Nov the set-up, trigger and exit boxes were empty; written reasons are what the review learns from."))
imp_process <- c(
  "Size every trade from the plan: the deal size is calculated so the money at risk equals your plan % (sizes 1-11 so far gave losses from \u00a30.13 to \u00a39.50).",
  "Trust measured chances only with enough cases (n of 30 or more) and track how well the measured chance and C's estimate predicted your real results (calibration table).",
  "Review weekly: expectancy in R by scenario source (Rules / C), by pattern, by session and by trend alignment; keep what has a positive expectancy, drop what has not.",
  "Keep the minimum Reward:Risk (box 2) at 1.5 or more: with a win rate of 40% a 1.5 R:R is about break-even, so the edge must come from selection.")
# from the LAT Level 5 Diploma study plan (materials index, 5 Nov 2026): ranked by how much each would improve trade decisions
# through the app. Same fields as imp_items: priority, title (course source), in the course, proposed here, why it helps.
imp_course <- list(
  list("High", "Structured Trading Plan, Trade Plan Template and Rule of Five (Week 4; Weeks 7-8)",
       "How to develop a structured trading plan, the trade plan template and the Rule of Five document.",
       "Turn your written plan into rules the app enforces: markets, sessions, set-ups allowed, risk %, minimum R:R, maximum trades per day, and the Rule of Five points as tick-box checks on the deal ticket; a deal that breaks a rule needs a written reason.",
       "Most losses come from trades outside the plan; making the plan a checklist at the moment of sending stops impulsive or oversized trades."),
  list("High", "LAT backtesting workbook and Trade Blotter (Introduction; Weeks 9-12)",
       "A backtesting spreadsheet and a trade blotter for the assessment trades.",
       "Backtest each strategy you use over Capital.com history in the app (win rate, expectancy in R, drawdown) before trading it, and keep the blotter automatically from your synced trades, exportable for the assessment.",
       "Only strategies with a positive tested expectancy get traded; the blotter shows at once which ones lose money live."),
  list("High", "Time-frame Analysis and Dow Theory (Week 2; Week 4)",
       "Reading the trend on higher time-frames first; Dow Theory phases of the market cycle.",
       "Every scenario shows the daily and 4-hour trend (Dow structure of highs and lows) and is marked with or against it; counter-trend deals need a higher R:R or are sized down.",
       "Trading with the higher time-frame trend raises the share of trades that reach the target; the 5 Nov trade was against the written trend."),
  list("High", "Economic Calendar Walkthrough and US Macro Crib Sheet (Introduction)",
       "Using the economic calendar and what each US release means for markets.",
       "Show the day's releases with the crib-sheet meaning next to each scenario in Plan & Order, and warn before opening a deal that a high-impact release falls inside the holding time.",
       "Avoids stops hit by news spikes and adds a reason (or a warning) to each trade."),
  list("Medium", "Course strategies: Short-Term Traders' Pivot Point System, The Holy Grail Trade, Straddle Trade System (Week 6; Weeks 7-8)",
       "Three complete strategies with entry, stop and target rules (and the Morning Straddle samples).",
       "Run each as a live scanner on Capital.com prices, using the course's exact rules, producing deal scenarios with their own measured record; today they appear as Step 6 examples only.",
       "Rule-based set-ups taught by the course, measured on your market, replace ad-hoc entries."),
  list("Medium", "Price/Time Filters (Week 2)",
       "Filters that confirm a break: a minimum distance beyond the level and / or a minimum time held.",
       "Apply a price and time filter before a breakout becomes a scenario (e.g. a close beyond the level by a set fraction of ATR, or held for N candles), with the filter shown in How.",
