       "A confluence score per scenario: trend (MAs, ADX / DMI), momentum (MACD, oscillators), volatility (Bollinger) and volume (OBV) agreeing or not; SAR as the trailing-stop suggestion.",
       "Trades where several independent signals agree tend to be the better ones; a low score is a reason to pass."),
  list("Medium", "Trading Psychology and the Attitude Survey (Week 4; Introduction)",
       "The psychology lecture and the attitude survey.",
       "Record mood and confidence before each deal and a short post-trade reflection; Statistics shows results by mood and after a loss (revenge-trade check).",
       "Shows when emotions, not the plan, are driving trades, and blocks trading straight after a run of losses."),
  list("Low", "Types of Investment Risk and Relative Value Trading (Week 2)",
       "Risk types and trading one market against a related one.",
       "Show related markets (e.g. Brent vs WTI, the dollar index) next to the chart and count correlated open risk together.",
       "Avoids doubling the same risk and adds context to oil moves."))

improvements_ui <- function(id) {
  ns <- NS(id)
  card <- function(x, rank, course = FALSE) { col <- c(High = "#b91c1c", Medium = "#b45309", Low = "#475569")[[x[[1]]]]
    tags$div(style = paste0("background:#fff; border:1px solid #e2e8f0; border-left:5px solid ", col, "; border-radius:8px; padding:10px 14px; margin:8px 0;"),
      tags$div(style = "font-weight:800; font-size:14.5px;", tags$span(style = "background:#111827; color:#fff; border-radius:4px; padding:1px 7px; margin-right:6px; font-size:12px;", paste0("#", rank)),
               tags$span(style = paste0("background:", col, "; color:#fff; border-radius:4px; padding:1px 7px; margin-right:8px; font-size:12px;"), x[[1]]), x[[2]]),
      tags$div(style = "font-size:13px; margin-top:4px;", tags$b(if (course) "In the course: " else "In the full app: "), x[[3]]),
      tags$div(style = "font-size:13px; margin-top:4px;", tags$b("Proposed here: "), x[[4]]),
      tags$div(style = "font-size:13px; margin-top:4px; color:#334155;", tags$b("Why it helps profit vs losses: "), x[[5]])) }
  tagList(
    tags$div(style = "background:linear-gradient(135deg,#0f172a,#0e7490); color:#fff; border-radius:12px; padding:14px 18px; margin-bottom:10px;",
      tags$h3(style = "margin:0;", "Improvements Proposed"),
      tags$p(style = "margin:6px 0 0 0;", "Left: from a review of the full LAT app. Right: from the LAT Level 5 Diploma study plan (materials index). Each list is ranked (#1 = most value for better trades) by what the app can do. ",
             "Proposals only; nothing is built until you ask.")),
    fluidRow(
      column(6, tags$div(style = "background:#fff; border-radius:8px; padding:8px 12px; margin:6px 0;", tags$h4(style = "color:#111827; font-weight:800; margin:0;", "Improvements based on full app"),
             tags$p(style = "font-size:12px; color:#334155; margin:2px 0 0 0;", "Modules of the full LAT app this app does not use yet, ranked by value for your trades.")),
             lapply(seq_along(imp_items), function(i) card(imp_items[[i]], i))),
      column(6, tags$div(style = "background:#fff; border-radius:8px; padding:8px 12px; margin:6px 0;", tags$h4(style = "color:#111827; font-weight:800; margin:0;", "Improvements based on the Study plan of LAT course"),
             tags$p(style = "font-size:12px; color:#334155; margin:2px 0 0 0;", "Lectures and documents of the Level 5 Diploma index turned into app features, ranked by value for your trades.")),
             lapply(seq_along(imp_course), function(i) card(imp_course[[i]], i, TRUE)))),
    tags$div(style = "background:#f0fdf4; border:1px solid #bbf7d0; border-radius:8px; padding:10px 14px; margin:10px 0;",
      tags$div(style = "font-weight:800;", "Process changes that need no new module"), tags$ul(lapply(imp_process, tags$li))),
    tags$div(style = "background:#fff; border:1px solid #cbd5e1; border-radius:8px; padding:10px 14px; margin:10px 0;",
      tags$div(style = "font-weight:800; color:#111827;", "Course coverage: every LAT topic and where it is in the app ****"),
      tags$p(style = "font-size:12px; color:#334155;", "Built items are marked * (first round), ** (second round), *** (Claude course checks) and **** (full coverage)."),
      tags$table(class = "table table-condensed table-striped", style = "font-size:12px;",
        tags$tr(lapply(names(cc_course_coverage), tags$th)),
        lapply(seq_len(nrow(cc_course_coverage)), function(i) { st <- cc_course_coverage$Status[i]
          tags$tr(tags$td(cc_course_coverage$Week[i]), tags$td(tags$b(cc_course_coverage$Topic[i])), tags$td(cc_course_coverage[[3]][i]),
                  tags$td(style = paste0("font-weight:700; color:", if (startsWith(st, "full")) "#166534" else if (startsWith(st, "partial")) "#b45309" else "#475569", ";"), st)) }))),
    tags$p(style = "font-size:12px; color:#64748b;", "Not proposed: options P&L, futures mechanics, hedging and yield-curve tabs: course material, not needed for intraday CFD decisions. ",
           "The full app's candlestick detection and blank trade-sheet form are already covered by the 141-pattern matrix and the Journal & Trade Sheet."))
}
